package com.example.orderdesk.order;

import static org.assertj.core.api.Assertions.assertThat;

import jakarta.validation.Validation;
import jakarta.validation.Validator;
import java.math.BigDecimal;
import org.junit.jupiter.api.Test;

class OrderLineTest {
  private final Validator validator = Validation.buildDefaultValidatorFactory().getValidator();

  @Test
  void quantityOf1000IsAccepted() {
    assertThat(validator.validate(new OrderLine("A-1", 1000, new BigDecimal("1.00")))).isEmpty();
  }

  @Test
  void quantityOf1001IsRejected() {
    assertThat(validator.validate(new OrderLine("A-1", 1001, new BigDecimal("1.00"))))
        .extracting(v -> v.getPropertyPath().toString()).containsExactly("quantity");
  }

  @Test
  void quantityOf0IsStillRejected() {
    assertThat(validator.validate(new OrderLine("A-1", 0, new BigDecimal("1.00"))))
        .extracting(v -> v.getPropertyPath().toString()).containsExactly("quantity");
  }
}
